#!/usr/bin/env python3
"""Build the public newsletter archive; no external dependencies or network calls."""
from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[1];D=R/'docs';D.mkdir(exist_ok=True);E=html.escape
weeks=sorted([json.loads(p.read_text()) for p in (R/'data').glob('week-*.json')],key=lambda w:w['week'],reverse=True)
def wrap(title,body,prefix=''):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Weekly fantasy football scoring, trends and matchup analysis for roblox and friends."><title>{E(title)} · roblox &amp; friends</title><link rel="stylesheet" href="{prefix}assets/style.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="{prefix}index.html">roblox <span>&amp;</span> friends</a><nav aria-label="Main navigation"><a href="{prefix}index.html">Reports</a><a href="{prefix}methodology.html">Methodology</a></nav></header><main id="main">{body}</main><footer><span>Commissioner’s statistical review · 2026 season</span><a href="{prefix}methodology.html">Sources &amp; model notes</a></footer></body></html>'''
def scores(w):
 rows=''
 for m in w['matchups']:
  a=next(t for t in m['teams'] if t['roster_id']==m['winner_id']);b=next(t for t in m['teams'] if t['roster_id']!=m['winner_id']);name=lambda x:'Alexis' if x.startswith('alexis') else x
  rows+=f'<tr><td>{E(name(a["name"]))}</td><td>{E(name(b["name"]))}</td><td class="num">{a["points"]:.2f}–{b["points"]:.2f}</td><td class="num">{m["margin"]:.2f}</td></tr>'
 return '<div class="table"><table><caption>Final matchup results</caption><thead><tr><th>Winner</th><th>Opponent</th><th>Final score</th><th>Margin</th></tr></thead><tbody>'+rows+'</tbody></table></div>'
latest=weeks[0];cards=''
for w in weeks:
 desc='jasmiine posts a season high; paulapun rebounds; btbchip wins five straight.' if w['week']==9 else 'A 1.36-point Monday finish, a 210-point leader, and three top-two weeks for Alexis.'
 cards+=f'<a class="report-card" href="reports/2026/week-{w["week"]:02}.html"><span class="eyebrow">2026 · WEEK {w["week"]}</span><h2>Week {w["week"]} statistical review <span aria-hidden="true">↗</span></h2><p>{desc}</p><span class="read">Read report →</span></a>'
body=f'''<section class="hero"><div><p class="eyebrow">FANTASY FOOTBALL · 2026 SEASON</p><h1>The week,<br>in numbers.</h1><p class="lead">Scoring trends, matchup context and the plays that changed the outlook.</p><a class="button" href="reports/2026/week-{latest['week']:02}.html">Read Week {latest['week']} →</a></div><aside class="hero-stat"><span class="eyebrow">LATEST WEEK</span><strong>207.13</strong><p>jasmiine’s season-high score</p><div><span>League average</span><b>154.73</b></div><div><span>Closest margin</span><b>17.57</b></div></aside></section><section><div class="section-heading"><h2>Weekly archive</h2><span>{len(weeks)} report{'s' if len(weeks)!=1 else ''} · Week {latest['week']}</span></div><div class="cards">{cards}</div></section><section class="panel"><p class="eyebrow">WEEK 9 RESULTS</p><h2>Four matchups. Final numbers.</h2>{scores(latest)}<p class="note">Results may change with NFL stat corrections.</p></section><section class="method-callout"><h2>More context than the raw score.</h2><p>Reports account for players still to play. Probability charts use an experimental model, with its assumptions and limitations published alongside the analysis.</p><a href="methodology.html">Read the methodology →</a></section>'''
(D/'index.html').write_text(wrap('Weekly archive',body))
for w in weeks:
 n=w['week'];content=(R/f'content/week-{n:02}.html').read_text();page=f'''<article><a class="back" href="../../index.html">← All reports</a><header class="report-header"><p class="eyebrow">2026 SEASON · WEEK {n}</p><h1>Week {n}<br>statistical review.</h1><p class="lead">Final scores, week-over-week trends and pivotal-play analysis.</p></header><section class="panel">{scores(w)}</section><div class="article-content">{content}</div><section><h2>Annotated matchup timelines</h2><p class="note">Tap the image to open it at full resolution. Idle gaps are compressed; real event times are retained. Changes show modeled scoring-only effects in percentage points.</p><a href="../../assets/week-{n:02}.png"><img class="graph" src="../../assets/week-{n:02}.png" alt="Four Week {n} matchup probability graphs, annotated with pivotal plays and compressed idle periods" loading="lazy"></a></section><aside class="model-note"><strong>About these estimates</strong><p>Probabilities are experimental estimates, not Sleeper’s archived live percentages. Projection history, injuries, correlations and late-game uncertainty remain approximate.</p><a href="../../methodology.html">Full methodology and sources →</a></aside><nav class="week-nav" aria-label="Weekly reports">'''+''.join(f'<a href="week-{x["week"]:02}.html">Week {x["week"]}</a>' for x in weeks)+'''</nav></article>'''
 target=D/f'reports/2026/week-{n:02}.html';target.parent.mkdir(parents=True,exist_ok=True);target.write_text(wrap(f'Week {n}',page,'../../'))
method='''<article><a class="back" href="index.html">← All reports</a><header class="report-header"><p class="eyebrow">TRANSPARENT BY DESIGN</p><h1>How the reports<br>are calculated.</h1></header><div class="article-content"><h2>Actual scores and effective lineups</h2><p>League scoring settings, weekly lineups and final points come from Sleeper.</p><h2>Scoring trends</h2><p>Week-over-week changes compare final team totals. Weekly ranks compare the eight teams. All-play records compare each team with all seven opponents each week. A 200-point week or scoring streak describes observed results, not future performance.</p><h2>Projected finishing scores</h2><p>At each timestamp: actual points plus the projected points still to come. Future NFL games retain their baseline; remaining projections decline with regulation game-clock time. Sleeper’s projected stats are rescored under this league’s rules. Missing custom defense counters use prior team history, shrunk toward the NFL league average.</p><h2>Experimental win probabilities</h2><p>Position-level uncertainty is fitted to prior-week projection errors. The primary model assumes independent Gaussian remaining-score errors, with variance declining with regulation time. It computes the chance one final score exceeds the other.</p><p>Shading changes uncertainty by ±20% and tests a chosen same-game correlation scenario. It is an assumption-sensitivity range, not a calibrated confidence interval.</p><h2>Pivotal-play labels</h2><p>We compare the post-play probability with a same-clock counterfactual removing that play’s net fantasy scoring. Clock and uncertainty stay fixed, and contributions to both fantasy teams on the same NFL play are combined. These percentage-point effects are not two consecutive historical live readings.</p><h2>Timeline display</h2><p>NFL game windows retain proportional real-time spacing. Gaps without any NFL games are shortened to narrow, hatched bands. Labels retain actual Pacific event times. The three largest absolute scoring effects per matchup are annotated.</p><h2>Limitations</h2><ul><li>Historical projection versions are not verified pre-kickoff archives. Effective lineups are held fixed retrospectively.</li><li>Injury exits, inactive status, possession and changing usage are not reconstructed.</li><li>Correlations are not learned, and defense thresholds are not simulated structurally.</li><li>Gaussian tails can allow implausible negative remaining contributions and distort late-game odds.</li><li>The model is not calibrated for precise historical live odds; use it for cautious comparisons and candidate pivotal moments.</li></ul><h2>Sources and attribution</h2><ul><li><a href="https://docs.sleeper.com/">Sleeper API</a>: league settings, matchup points, rosters and player metadata. Weekly stats and projections use undocumented endpoints.</li><li><a href="https://github.com/nflverse/nflverse-data">nflverse / nflfastR</a>: processed play-by-play, with raw NFL game data used when a cleaned game was not yet available. Data attribution: CC BY 4.0.</li><li><a href="https://github.com/dynastyprocess/data">DynastyProcess / ffverse</a>: cross-platform player IDs.</li></ul><p>Reports are snapshots and may change after stat corrections. No visitor account, live data collection or backend is required.</p></div></article>'''
(D/'methodology.html').write_text(wrap('Methodology',method));(D/'.nojekyll').touch();print('Built',len(weeks),'weekly reports plus homepage and methodology')
